#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Guard against invalid/mismatched input sizes and overflow in N*N.
    if (A.size() / N < N) {
        return 0;
    }

    int max_degree = 0;

    #pragma omp parallel for reduction(max:max_degree) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        int row_degree = 0;
        const size_t base = static_cast<size_t>(i) * N;

        for (size_t j = 0; j < N; ++j) {
            if (A[base + j] != 0) {
                ++row_degree;
            }
        }

        if (row_degree > max_degree) {
            max_degree = row_degree;
        }
    }

    return max_degree;
}
